from datetime import date, timedelta

def following(d):
    while d.weekday() > 4:
        d += timedelta(days=1)
    return d

def preceding(d):
    while d.weekday() > 4:
        d -= timedelta(days=1)
    return d

def modified_following(d):
    f = following(d)
    return preceding(d) if f.month != d.month else f

