import calendar
from datetime import date, timedelta

def nth_formula(y, m, wd, n):
    d = date(y, m, 1)
    return d + timedelta(days=(wd - d.weekday()) % 7 + 7 * (n - 1))

def nth_brute(y, m, wd, n):
    seen = 0
    for day in range(1, calendar.monthrange(y, m)[1] + 1):
        d = date(y, m, day)
        if d.weekday() == wd:
            seen += 1
            if seen == n:
                return d

compared = disagreements = 0
for y in (2026, 2027):
    for m in range(1, 13):
        for wd in range(7):
            for n in range(1, 5):
                compared += 1
                if nth_formula(y, m, wd, n) != nth_brute(y, m, wd, n):
                    disagreements += 1
print("comparisons:", compared)
print("disagreements:", disagreements)

